<template><view :class="['slide-drop-target',{ready,accepted}]" :style="targetStyle"><view class="drop-orbit orbit-one"/><view class="drop-orbit orbit-two"/><view class="drop-orbit orbit-three"/><view class="drop-core"><Icon :name="mode==='review'?'repeat':'check'"/><Bi :zh="mode==='review'?'复习':'已会'" :fr="mode==='review'?'Révision':'Acquis'" small/></view><view class="drop-sparks" aria-hidden="true"><i v-for="n in 8" :key="n" :style="{'--angle':(n*45)+'deg'}"/></view></view></template>
