<style scoped>
.slide-drop-target{position:absolute;width:88px;height:88px;transform:translate(-50%,-50%);display:grid;place-items:center;color:var(--accent-dark);isolation:isolate}.drop-core{position:relative;z-index:1;width:76px;height:76px;border:1px solid rgba(var(--theme-rgb),.4);border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;background:var(--theme-panel,#f8faff);box-shadow:0 5px 24px rgba(var(--theme-rgb),.12),0 0 0 calc(var(--near)*7px) rgba(var(--theme-rgb),.1);transform:scale(calc(.94 + var(--near)*.1));transition:transform .16s ease-out,box-shadow .16s ease-out,background .18s,border-color .18s}.drop-core>.icon{width:22px;height:22px}.drop-core :deep(.bi-zh){font-size:12px}.drop-core :deep(.bi-fr){font-size:9px}.drop-core :deep(.bi){align-items:center;text-align:center;gap:0}.drop-orbit{position:absolute;inset:-17px;border:1px solid rgba(var(--theme-rgb),.3);border-radius:50%;opacity:0;animation:drop-inward 1.8s cubic-bezier(.25,.5,.45,1) infinite;pointer-events:none}.orbit-two{animation-delay:-.6s}.orbit-three{animation-delay:-1.2s}.ready .drop-core{border-color:var(--accent);background:var(--theme-soft);box-shadow:0 0 0 8px rgba(var(--theme-rgb),.12),0 8px 28px rgba(var(--theme-rgb),.2);transform:scale(1.08)}.ready .drop-orbit{animation-duration:1.1s}.accepted .drop-core{animation:drop-collect .46s cubic-bezier(.18,.7,.25,1) both}.accepted .drop-orbit{animation:none;opacity:0}.drop-sparks{position:absolute;inset:0;z-index:2;display:none}.accepted .drop-sparks{display:block}.drop-sparks>i{position:absolute;left:50%;top:50%;width:4px;height:4px;border-radius:50%;background:var(--accent);animation:drop-spark .46s ease-out both;transform:rotate(var(--angle)) translateY(-32px)}@keyframes drop-inward{0%{opacity:0;transform:scale(1)}22%{opacity:.55}100%{opacity:0;transform:scale(.56)}}@keyframes drop-collect{0%{transform:scale(1.08)}32%{transform:scale(.94)}65%{transform:scale(1.12)}100%{transform:scale(1);opacity:0}}@ke